from taf.ul.log_collection.config.builders.util import split_and_remove_blank_spaces
from taf.internal.execution.local.local_executor import LocalExecutor
import re

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ClassicalGnbUplaneTraceCollectorConfigurator:

    def add_uplane_trace(self, ne_log_name, ne_log_configuration):
        destination_port_number = 5678
        components_list = split_and_remove_blank_spaces(ne_log_configuration['components'])
        l2ps_profile_filter_list = ne_log_configuration.get('l2ps_profile_filter_list')

        self.validate_and_create_l2_stream_configuration(
            ne_log_name=ne_log_name,
            components_list=components_list,
            destination_port_number=destination_port_number,
            l2ps_profile_filter_list=l2ps_profile_filter_list)

    def validate_and_create_l2_stream_configuration(self, ne_log_name, components_list,
                                                    destination_port_number, l2ps_profile_filter_list):
        allowed_components = {'L2Ps', 'L2Lo', 'L2HiPdcp', 'L2HiRlc'}

        def normalize(component):
            return {component.lower(): component for component in allowed_components}[component]

        normalized_components_list = []
        for component in components_list:
            try:
                normalized_components_list.append(
                    normalize(component.translate(str.maketrans('', '', "-_ ")).lower()))
            except KeyError:
                raise ValueError(f"invalid component: {component!r}")
        l2_stream_configuration = []
        for component in normalized_components_list:
            if l2ps_profile_filter_list and component == 'L2Ps':
                l2_stream_configuration.append(
                    {
                        'up_sw': component,
                        'profile_filter_list': split_and_remove_blank_spaces(l2ps_profile_filter_list)})
            else:
                l2_stream_configuration.append({'up_sw': component})

        self._add_tcpdump_collector_configuration(
            ne_log_name, destination_port_number)
        self._add_l2_stream_collector_configuration(
            ne_log_name, l2_stream_configuration, destination_port_number)

    def _add_tcpdump_collector_configuration(self, ne_log_name, destination_port_number):
        tcpdump_collector_configuration = {
            'name': f'{ne_log_name}_tcpdump',
            'options': f'-i eth3 -n -s 0 udp port {destination_port_number}',
            'type': 'tcpdump'
        }
        self._collector_configuration_data.append(tcpdump_collector_configuration)

    def _add_l2_stream_collector_configuration(self, ne_log_name, l2_stream_configuration, destination_port_number):
        oam_http_connection = self.tl_config_information_provider.get_web_service(node_id=self.ne_id)
        logger.info("oam host ip address: ", oam_http_connection['host'])

        source_ip_address = self.sbts_oam_information_provider.get_mplane_ip_address()
        destination_ip_addr = self._get_l2_stream_destination_ip_address()

        l2_stream_collector_configuration = {
            'name': ne_log_name,
            'type': 'l2stream3_sbts',
            'l2_stream_configuration': l2_stream_configuration,
            'source_ip_addr': source_ip_address,          # '10.0.1.2'
            'destination_ip_addr':  destination_ip_addr,  # '10.0.1.1'
            'dscp': 15,
            'destination_port_number': destination_port_number,
            'webservice': {
                'host': oam_http_connection['host'],
                'user': oam_http_connection['user'],
                'password': oam_http_connection['password']
            },
            'collector': f'{ne_log_name}_tcpdump'
        }
        self._collector_configuration_data.append(l2_stream_collector_configuration)
        if 'L2Ps' in l2_stream_configuration[0]['up_sw']:
            self._collector_configuration_data.add_mapping_entry(
                log_type='uplane_trace',
                network_element=f'{self.ne_type}_{self.ne_id}',
                collector_configuration=l2_stream_collector_configuration)

    def _get_l2_stream_destination_ip_address(self):

        mplane_ip_addr = self.sbts_oam_information_provider.get_mplane_ip_address()

        executor = LocalExecutor()
        stdout = executor.execute(command="ip route get %s" % mplane_ip_addr, use_tty=False)

        result = re.search(r'src\s+(\d+\.\d+\.\d+\.\d+)', str(stdout))
        destination_ip_addr = result.group(1)

        logger.info("l2_stream destination ip address : %s is set", destination_ip_addr)

        return destination_ip_addr
